import XCTest

/// From-zero UI scenarios. Run only with the separate QA bundle generated by
/// generate_release_inputs.py --qa; no real provider or existing household needed.
final class FamilyReviewUITests: XCTestCase {
    @MainActor private func amountSortLaunch() -> XCUIApplication {
        continueAfterFailure = false
        let app = XCUIApplication()
        app.launchArguments = ["--qa-isolated","--qa-amount-sort","--qa-reset-amount-sort"]
        app.launch()
        XCTAssertTrue(app.staticTexts["已记录净消费"].waitForExistence(timeout:30))
        return app
    }
    @MainActor private func amountText(_ id: String, app: XCUIApplication) -> XCUIElement {
        app.staticTexts["transaction-amount:" + id]
    }
    @MainActor func testAmountSortDetailsCategorySearchAndPaginationReadOnly() {
        let app = amountSortLaunch()
        app.tabBars.buttons["明细"].tap()
        let multi = amountText("sort-multi",app:app), credit = amountText("sort-credit",app:app), high = amountText("sort-high",app:app)
        XCTAssertTrue(multi.waitForExistence(timeout:5)); XCTAssertTrue(multi.label.contains("910.00"))
        XCTAssertLessThan(multi.frame.minY,credit.frame.minY); XCTAssertLessThan(credit.frame.minY,high.frame.minY)
        capture(app,"amount-01-details-global-descending")
        let search = app.searchFields.firstMatch; search.tap(); search.typeText("同额")
        if app.buttons["完成输入"].exists { app.buttons["完成输入"].tap() }
        let newer = amountText("sort-tie-b",app:app), older = amountText("sort-tie-a",app:app)
        XCTAssertTrue(newer.waitForExistence(timeout:5)); XCTAssertLessThan(newer.frame.minY,older.frame.minY)
        capture(app,"amount-02-search-same-amount-date-order")
        app.buttons["取消"].tap()
        app.staticTexts["排序：组合购买 910元"].firstMatch.tap()
        XCTAssertTrue(app.navigationBars["交易详情"].waitForExistence(timeout:5))
        XCTAssertTrue(app.staticTexts["排序：组合设备 900元"].firstMatch.exists)
        capture(app,"amount-03-full-lifecycle-detail")
        app.navigationBars.buttons.firstMatch.tap(); XCTAssertTrue(app.navigationBars["支出明细"].exists)
        app.tabBars.buttons["复盘"].tap()
        let category = app.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","日常消费")).firstMatch
        reveal(category,in:app); category.tap()
        let secondary = app.buttons["category-transactions:日常消费/咖啡茶饮"]
        reveal(secondary,in:app); secondary.tap()
        let first = amountText("sort-single",app:app); reveal(first,in:app)
        XCTAssertTrue(first.label.contains("300.00"))
        capture(app,"amount-04-category-projected-net-descending")
        let more = app.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","显示更多（剩余")).firstMatch
        reveal(more,in:app,maxSwipes:22); capture(app,"amount-05-category-first-page-footer"); more.tap()
        let projected = amountText("sort-multi",app:app); reveal(projected,in:app,maxSwipes:22)
        XCTAssertEqual(projected.label,"¥10.00")
        let end = amountText("sort-page-31",app:app); reveal(end,in:app,maxSwipes:22)
        XCTAssertEqual(end.label,"¥1.00"); capture(app,"amount-06-category-appended-smallest")
        end.tap(); XCTAssertTrue(app.navigationBars["交易详情"].waitForExistence(timeout:5))
        capture(app,"amount-07-category-row-opens-full-detail")
        app.terminate()
    }
    @MainActor func testAmountSortCompletionRefundTargetsAndEvidenceReadOnly() {
        let app = amountSortLaunch()
        app.tabBars.buttons["补全"].tap()
        let credit = app.staticTexts["completion-amount:sort-credit:facts"], high = app.staticTexts["completion-amount:sort-high"]
        reveal(credit,in:app); XCTAssertTrue(credit.label.contains("700.00")); XCTAssertLessThan(credit.frame.minY,high.frame.minY)
        capture(app,"amount-08-completion-impact-descending")
        queue("待分类",app:app)
        let zero = app.staticTexts["completion-amount:sort-zero"], unknown = app.staticTexts["completion-amount:sort-unknown"]
        reveal(high,in:app); XCTAssertTrue(high.label.contains("500.00"))
        XCTAssertLessThan(high.frame.minY,zero.frame.minY); XCTAssertLessThan(zero.frame.minY,unknown.frame.minY)
        XCTAssertEqual(unknown.label,"金额未知"); capture(app,"amount-09-completion-known-before-unknown")
        queue("待核事实",app:app); reveal(credit,in:app)
        app.staticTexts["排序：退款来源 700元"].firstMatch.tap()
        let facts = app.buttons["transaction-facts"]; reveal(facts,in:app); facts.tap()
        let disposition = app.buttons["fact-disposition"]; XCTAssertTrue(disposition.waitForExistence(timeout:5)); disposition.tap()
        app.buttons["确认退款，关联原购买项目"].tap()
        app.buttons["fact-target"].tap()
        XCTAssertTrue(app.navigationBars["原购买项目"].waitForExistence(timeout:5))
        let large = app.staticTexts["排序：组合设备 900元"], small = app.staticTexts["排序：组合咖啡 10元"]
        XCTAssertTrue(large.exists); XCTAssertLessThan(large.frame.minY,app.staticTexts["排序：待分类 500元"].frame.minY)
        capture(app,"amount-10-refund-targets-flattened-component-order")
        let targetSearch = app.searchFields.firstMatch; targetSearch.tap(); targetSearch.typeText("组合")
        if app.buttons["完成输入"].exists { app.buttons["完成输入"].tap() }
        XCTAssertLessThan(large.frame.minY,small.frame.minY)
        capture(app,"amount-11-refund-target-search-preserves-order")
        app.navigationBars["原购买项目"].buttons["取消"].tap()
        // Close the unsaved form; navigation and search must not save facts.
        app.buttons["关闭"].tap()
        app.tabBars.buttons["资料"].tap()
        let evidence = app.buttons["交易证据与关联复核"]; reveal(evidence,in:app); evidence.tap()
        XCTAssertTrue(app.navigationBars["交易证据"].waitForExistence(timeout:5))
        let candidateHigh = app.staticTexts["隔离排序候选 qa-high"], candidateLow = app.staticTexts["隔离排序候选 qa-low"]
        XCTAssertLessThan(candidateHigh.frame.minY,candidateLow.frame.minY); capture(app,"amount-12-evidence-candidates-largest-first")
        candidateHigh.tap(); XCTAssertTrue(app.navigationBars["关联复核"].waitForExistence(timeout:5))
        capture(app,"amount-13-candidate-participants-descending")
        app.navigationBars.buttons.firstMatch.tap()
        let picker = app.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","证据视角")).firstMatch
        picker.tap(); app.buttons["原始记录"].tap()
        XCTAssertLessThan(app.staticTexts["隔离排序证据 900元"].frame.minY,app.staticTexts["隔离排序证据 500元"].frame.minY)
        capture(app,"amount-14-evidence-records-descending")
        app.staticTexts["隔离排序证据 900元"].tap(); XCTAssertTrue(app.navigationBars["原始证据"].waitForExistence(timeout:5))
        capture(app,"amount-15-original-evidence-detail")
        app.navigationBars.buttons.firstMatch.tap(); XCTAssertTrue(app.navigationBars["交易证据"].exists)
        app.terminate()
    }
    @MainActor private func capture(_ app: XCUIApplication, _ name: String) {
        let attachment = XCTAttachment(screenshot: app.screenshot()); attachment.name = name; attachment.lifetime = .keepAlways; add(attachment)
        if name.contains("quicklook") { print("QA_SCREEN \(name) QuickLook overlay visible") }
        else { print("QA_SCREEN \(name)\n\(app.debugDescription)") }
    }
    @MainActor private func reveal(_ element: XCUIElement, in app: XCUIApplication, maxSwipes: Int = 14) {
        for _ in 0..<maxSwipes {
            if element.exists && element.isHittable && (element.elementType != .textField || element.frame.maxY < app.frame.height * 0.55) { return }
            let down = element.exists && element.frame.midY < 100
            app.coordinate(withNormalizedOffset:CGVector(dx:0.1,dy:down ? 0.26 : 0.60)).press(forDuration:0.05,thenDragTo:app.coordinate(withNormalizedOffset:CGVector(dx:0.1,dy:down ? 0.60 : 0.24)))
        }
        XCTAssertTrue(element.exists && element.isHittable,"Element must become visible: " + element.description)
    }
    @MainActor private func queue(_ mode: String, app: XCUIApplication) {
        app.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","处理队列")).firstMatch.tap()
        app.buttons[mode].tap()
    }
}
